//! A repeat's `t` follows its cubic, and a detached repeat runs straight.
//!
//! `repeats.xodr` is generated by `scenariogeneration` (see `repeats.py`).
//! Its road 1 is an 80 m left arc of radius 100 m from the origin heading
//! +X, at elevation `0.002 s^2`, so every placement has a closed form.

use xodr::{load_file_with_provenance, Object, Point, Provenance, RoadNetwork, Shape, Warning};

const REPEATS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/repeats.xodr");

const RADIUS: f64 = 100.0;

fn load() -> (RoadNetwork, Provenance) {
    load_file_with_provenance(REPEATS).expect("import")
}

/// The road surface at `(s, t)`.
fn ground(s: f64, t: f64) -> Point {
    let hdg = s / RADIUS;
    Point::new(
        ((RADIUS - t) * hdg.sin()) as f32,
        (RADIUS - (RADIUS - t) * hdg.cos()) as f32,
        (0.002 * s * s) as f32,
    )
}

/// The `(s, t)` of a point on the road, in plan.
fn station(p: Point) -> (f64, f64) {
    let (x, y) = (f64::from(p.x), RADIUS - f64::from(p.y));
    (RADIUS * x.atan2(y), RADIUS - x.hypot(y))
}

fn named<'a>(net: &'a RoadNetwork, name: &str) -> Vec<&'a Object> {
    net.objects().iter().filter(|o| o.name == name).collect()
}

fn position(object: &Object) -> Point {
    match object.shape {
        Shape::Solid { position, .. } => position,
        ref other => panic!("{} is not a solid: {other:?}", object.name),
    }
}

fn assert_near(got: Point, want: Point, what: &str) {
    assert!(
        (got - want).length() < 1e-3,
        "{what}: got {got:?}, expected {want:?}"
    );
}

/// The midpoint of each section of a sweep, with its two edges.
fn sections(object: &Object) -> Vec<(Point, Point, Point)> {
    let Shape::Sweep { sections, .. } = &object.shape else {
        panic!("{} is not a sweep: {:?}", object.name, object.shape);
    };
    sections
        .iter()
        .map(|s| {
            (
                s.left.base.lerp(s.right.base, 0.5),
                s.left.base,
                s.right.base,
            )
        })
        .collect()
}

fn mismatches(provenance: &Provenance) -> Vec<(String, f64, f64)> {
    provenance
        .warnings
        .iter()
        .filter_map(|w| match w {
            Warning::RepeatEndMismatch {
                object_id,
                t_end,
                reached,
                ..
            } => Some((object_id.clone(), *t_end, *reached)),
            _ => None,
        })
        .collect()
}

#[test]
fn copies_of_a_repeat_follow_its_cubic_t() {
    let (net, _) = load();
    let drift = named(&net, "Drift");
    assert_eq!(drift.len(), 5);
    for (k, copy) in drift.iter().enumerate() {
        let ds = 5.0 * k as f64;
        let t = -4.0 + 0.05 * ds + 0.002 * ds * ds + 0.0001 * ds * ds * ds;
        assert_near(position(copy), ground(10.0 + ds, t), &format!("copy {k}"));
    }
}

#[test]
fn a_continuous_repeat_follows_its_cubic_t() {
    let (net, _) = load();
    let [kink] = named(&net, "Kink")[..] else {
        panic!("one kink");
    };
    let mids = sections(kink);
    assert!(mids.len() > 2, "{} sections", mids.len());
    for (mid, ..) in mids {
        let (s, t) = station(mid);
        let ds = s - 40.0;
        let want = 2.0 + 0.1 * ds + 0.0001 * ds * ds * ds;
        assert!((t - want).abs() < 1e-3, "at s={s}: t {t}, expected {want}");
    }
    let (first, ..) = sections(kink)[0];
    assert_near(first, ground(40.0, 2.0), "start");
    let (last, ..) = *sections(kink).last().unwrap();
    assert_near(last, ground(60.0, 4.8), "end");
}

#[test]
fn a_detached_repeat_places_its_copies_on_the_straight_line_between_its_ends() {
    let (net, _) = load();
    let chord = named(&net, "Chord");
    assert_eq!(chord.len(), 5);
    let (a, b) = (ground(0.0, -5.0), ground(40.0, -7.0));
    for (k, copy) in chord.iter().enumerate() {
        let want = a.lerp(b, k as f32 / 4.0);
        assert_near(position(copy), want, &format!("post {k}"));
    }
    let (s, t) = station(position(chord[2]));
    assert!(
        (t + 6.0).abs() > 1.0,
        "the middle post at s={s} sits at t={t}, on the arc"
    );
}

#[test]
fn a_detached_continuous_repeat_runs_straight_and_square_to_its_line() {
    let (net, _) = load();
    let [wall] = named(&net, "Wall")[..] else {
        panic!("one wall");
    };
    let (a, b) = (ground(40.0, -6.0), ground(80.0, -6.0));
    let along = (b - a).normalize_or_zero();
    let mids = sections(wall);
    assert!(mids.len() >= 2, "{} sections", mids.len());
    for (mid, left, right) in mids {
        let off = mid - a;
        let aside = off - along * off.dot(along);
        assert!(aside.length() < 1e-3, "{mid:?} is {aside:?} off the line");
        let across = left - right;
        assert!((across.length() - 0.3).abs() < 1e-4, "{across:?} across");
        assert!(across.dot(along).abs() < 1e-4, "{across:?} not square");
        assert!(across.z.abs() < 1e-6, "{across:?} not level");
    }
    assert_near(sections(wall)[0].0, a, "start");
    assert_near(sections(wall).last().unwrap().0, b, "end");
}

#[test]
fn a_cubic_that_misses_its_t_end_is_followed_with_a_warning() {
    let (net, provenance) = load();
    assert_eq!(
        mismatches(&provenance),
        [
            ("5".to_string(), 1.0, 2.0),
            ("6".to_string(), 3.0, 2.0),
            ("7".to_string(), 4.0, 3.0)
        ]
    );
    for (k, copy) in named(&net, "Stray").iter().enumerate() {
        let ds = 5.0 * k as f64;
        assert_near(position(copy), ground(60.0 + ds, 1.0 + 0.1 * ds), "stray");
    }
}

#[test]
fn coefficients_of_zero_hold_t_at_its_start() {
    let (net, _) = load();
    let flat = named(&net, "Flat");
    assert_eq!(flat.len(), 3);
    for (k, copy) in flat.iter().enumerate() {
        assert_near(position(copy), ground(5.0 * k as f64, 2.0), "flat");
    }
}

#[test]
fn a_negative_coefficient_is_read_as_written() {
    let (net, _) = load();
    let right = named(&net, "Right");
    assert_eq!(right.len(), 3);
    for (k, copy) in right.iter().enumerate() {
        let ds = 5.0 * k as f64;
        assert_near(position(copy), ground(20.0 + ds, 4.0 - 0.1 * ds), "right");
    }
}
